tool_input.command:
node -e '
const retry = (body, what) => `SET statement_timeout = 0; DO $$ BEGIN PERFORM set_config($q$lock_timeout$q$, $q$300ms$q$, true); FOR i IN 1..120 LOOP BEGIN ${body} RETURN; EXCEPTION WHEN lock_not_available THEN PERFORM pg_sleep(0.2); END; END LOOP; RAISE EXCEPTION $q$could not lock orders to ${what}$q$; END $$;`;
const steps = [];
steps.push({note: "Pre-flight: orders.customer_id must still be integer NOT NULL, and customer_id_new must not exist yet.",
  sql: "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = $q$public$q$ AND table_name = $q$orders$q$ AND column_name = $q$customer_id$q$ AND data_type = $q$integer$q$ AND is_nullable = $q$NO$q$) THEN RAISE EXCEPTION $q$orders.customer_id is not integer NOT NULL$q$; END IF; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = $q$public$q$ AND table_name = $q$orders$q$ AND column_name = $q$customer_id_new$q$) THEN RAISE EXCEPTION $q$orders.customer_id_new already exists$q$; END IF; END $$;"});
steps.push({note: "Trigger function that copies customer_id into the new bigint column on every insert (and on any update of customer_id).",
  sql: "CREATE FUNCTION orders_customer_id_sync() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.customer_id_new := NEW.customer_id; RETURN NEW; END $$;"});
steps.push({note: "Add nullable bigint column customer_id_new (metadata-only, no rewrite) and the sync trigger, in one short ACCESS EXCLUSIVE lock. lock_timeout 300ms with retries so app queries never queue behind us for long.",
  sql: retry("ALTER TABLE orders ADD COLUMN customer_id_new bigint; CREATE TRIGGER orders_customer_id_sync BEFORE INSERT OR UPDATE OF customer_id ON orders FOR EACH ROW EXECUTE FUNCTION orders_customer_id_sync();", "add column")});
const B = 200000, END = 10200000;
let sql = [];
for (let lo = 1, n = 0; lo <= END; lo += B, n++) {
  const hi = lo + B - 1;
  sql.push(`UPDATE orders SET customer_id_new = customer_id WHERE id BETWEEN ${lo} AND ${hi} AND customer_id_new IS NULL;`);
  if (sql.length === 5 || hi >= END) {
    const last = hi >= END;
    if (last) sql.push(`UPDATE orders SET customer_id_new = customer_id WHERE id > ${END} AND customer_id_new IS NULL;`);
    const from = lo - B * (last ? sql.length - 2 : sql.length - 1);
    steps.push({note: `Backfill ids ${from}..${last ? "end" : hi} in 200k-row autocommitted batches (app only inserts, so no row-lock conflicts), then VACUUM without truncation (no ACCESS EXCLUSIVE) so dead tuples are reused and the table does not double in size.`,
      sql: "SET statement_timeout = 0; " + sql.join(" ") + " VACUUM (TRUNCATE false) orders;"});
    sql = [];
  }
}
steps.push({note: "Add NOT VALID check constraints (brief lock, with retries): new column is NOT NULL and equals customer_id. They are enforced for every new row from now on.",
  sql: retry("ALTER TABLE orders ADD CONSTRAINT orders_customer_id_new_not_null CHECK (customer_id_new IS NOT NULL) NOT VALID; ALTER TABLE orders ADD CONSTRAINT orders_customer_id_new_eq CHECK (customer_id_new = customer_id) NOT VALID;", "add check constraints")});
steps.push({note: "Validate both constraints: full scan under SHARE UPDATE EXCLUSIVE, which does not block the app. Fails the plan if any row was missed or differs.",
  sql: "SET statement_timeout = 0; ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_new_not_null; ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_new_eq;"});
steps.push({note: "Swap in one short transaction (with retries): SET NOT NULL (no scan, proven by the validated check), drop trigger and checks, drop the old integer column, rename customer_id_new to customer_id.",
  sql: retry("ALTER TABLE orders ALTER COLUMN customer_id_new SET NOT NULL; DROP TRIGGER orders_customer_id_sync ON orders; ALTER TABLE orders DROP CONSTRAINT orders_customer_id_new_eq; ALTER TABLE orders DROP CONSTRAINT orders_customer_id_new_not_null; ALTER TABLE orders DROP COLUMN customer_id; ALTER TABLE orders RENAME COLUMN customer_id_new TO customer_id;", "swap columns") + " DROP FUNCTION orders_customer_id_sync();"});
steps.push({note: "Verify: orders.customer_id is now bigint NOT NULL. Refresh planner statistics for the new column.",
  sql: "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = $q$public$q$ AND table_name = $q$orders$q$ AND column_name = $q$customer_id$q$ AND data_type = $q$bigint$q$ AND is_nullable = $q$NO$q$) THEN RAISE EXCEPTION $q$orders.customer_id is not bigint NOT NULL$q$; END IF; END $$; SET statement_timeout = 0; ANALYZE orders;"});
require("fs").writeFileSync("plans/plain-customer-bigint-1.json", JSON.stringify({task: "customer-bigint", steps}, null, 2) + "\n");
console.log(steps.length);
' && head -c 1500 plans/plain-customer-bigint-1.json
